"""Tokenizer and recursive-descent parser for the SQL interface."""
from dataclasses import dataclass, field
from decimal import Decimal
import re
from typesystem import *

@dataclass
class Token:
    value:str
    raw:str
    pos:int
    kind:str='word'
    @property
    def upper(self): return self.value.upper() if self.kind not in ('string','qid') else self.value

@dataclass
class Node:
    k:str
    v:object=None
    a:list=field(default_factory=list)
    pos:int=0
    extra:dict=field(default_factory=dict)
    def name(self):
        k,v,a=self.k,self.v,self.a
        if k=='lit':
            if v is None: return 'NULL'
            if isinstance(v,bool): return "CAST('%s' AS BOOLEAN)"%('t' if v else 'f')
            if isinstance(v,str): return "'"+v.replace("'","''")+"'"
            if isinstance(v,Decimal): return format(v,'f')
            return valstr(v)
        if k=='col': return '.'.join(quote_ident(s) for s in v)
        if k=='star': return ('.'.join(v)+'.' if v else '')+'*'
