        if k=='unary': return ('(NOT '+a[0].name()+')') if v=='NOT' else '('+v+a[0].name()+')'
        if k=='is': return '('+a[0].name()+' IS '+v+')'
        if k=='between': return '('+a[0].name()+(' NOT' if v else '')+' BETWEEN '+a[1].name()+' AND '+a[2].name()+')'
        if k=='in': return '('+a[0].name()+(' NOT' if v else '')+' IN ('+', '.join(x.name() for x in a[1:])+'))'
