        if k=='struct': return 'main.struct_pack('+', '.join(quote_ident(n)+' := '+x.name() for n,x in zip(v,a))+')'
        if k=='index': return a[0].name()+'['+a[1].name()+']'
        if k=='slice': return a[0].name()+'['+('' if a[1] is None else a[1].name())+':'+('' if a[2] is None else a[2].name())+']'
        if k=='field': return '('+a[0].name()+').'+quote_ident(v)
