        if k=='exists': return 'EXISTS(SELECT ...)'
        if k=='lambda': return '('+a[0].name()+' -> '+a[1].name()+')'
        return str(v)


def tokenize(s):
    ts=[]; i=0; n=len(s)
    while i<n:
        c=s[i]
        if c.isspace(): i+=1; continue
        if s.startswith('--',i):
            j=s.find('\n',i); i=n if j<0 else j+1; continue
        if s.startswith('/*',i):
            start=i; i+=2; depth=1
            while i<n and depth:
                if s.startswith('/*',i): depth+=1; i+=2
                elif s.startswith('*/',i): depth-=1; i+=2
                else: i+=1
            if depth: raise SQLError('Parser','unterminated /* comment at or near "'+s[start:]+'"',start)
            continue
        start=i
        escape=False
        if c in 'eE' and i+1<n and s[i+1]=="'": escape=True; i+=1; c="'"
        if c in ("'",'"'):
            i+=1; chars=[]
            while i<n:
                if s[i]==c:
                    if i+1<n and s[i+1]==c: chars.append(c); i+=2
                    else: i+=1; break
                elif escape and s[i]=='\\' and i+1<n:
                    nxt=s[i+1]; chars.append({'n':'\n','t':'\t','r':'\r','b':'\b','0':'\0'}.get(nxt,nxt)); i+=2
                else: chars.append(s[i]); i+=1
            else: raise SQLError('Parser','unterminated quoted '+('string' if c=="'" else 'identifier')+' at or near "'+s[start:]+'"',start)
            ts.append(Token(''.join(chars),s[start:i],start,'string' if c=="'" else 'qid')); continue
        if c=='$':
            m=re.match(r'\$[a-zA-Z_0-9]*\$',s[i:])
            if m:
                tag=m[0]; j=s.find(tag,i+len(tag))
                if j<0: raise SQLError('Parser','unterminated dollar-quoted string at or near "'+s[i:]+'"',i)
                ts.append(Token(s[i+len(tag):j],s[i:j+len(tag)],i,'string')); i=j+len(tag); continue
        m=re.match(r'(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?',s[i:])
        if m:
            i+=len(m[0]); ts.append(Token(m[0],m[0],start,'number')); continue
        m=re.match(r'[a-zA-Z_\u0080-\uffff][\w$]*',s[i:])
        if m:
            i+=len(m[0]); ts.append(Token(m[0],m[0],start)); continue
        m=re.match(r'->>|::|:=|=>|->|\|\||//|\*\*|<=|>=|<>|!=|!~~\*?|~~\*?|!~\*?|~\*|<<|>>',s[i:])
        raw=m[0] if m else c; i+=len(raw); ts.append(Token(raw,raw,start,'symbol'))
    ts.append(Token('EOF','',len(s),'eof'))
    return ts

STOP_ALIAS=set('FROM WHERE GROUP HAVING QUALIFY ORDER LIMIT OFFSET UNION INTERSECT EXCEPT JOIN INNER LEFT RIGHT FULL CROSS NATURAL SEMI ANTI ASOF ON USING RETURNING WINDOW FETCH FOR PIVOT UNPIVOT SET VALUES INTO WHEN THEN ELSE END ASC DESC NULLS AND OR BY ALL FILTER OVER ROWS RANGE EXCLUDE REPLACE RENAME SAMPLE TABLESAMPLE'.split())
PRECEDENCE={'OR':10,'AND':20,'=':30,'==':30,'<>':30,'!=':30,'<':30,'>':30,'<=':30,'>=':30,'IS':30,'IN':30,'BETWEEN':30,'LIKE':30,'ILIKE':30,'SIMILAR':30,'NOT':30,'~':30,'!~':30,'~~':30,'!~~':30,'~~*':30,'!~~*':30,'|':35,'&':36,'<<':37,'>>':37,'||':40,'+':50,'-':50,'*':60,'/':60,'//':60,'%':60,'^':70,'**':70,'->':5,'->>':5}

class Parser:
    def __init__(self,s,tokens=None): self.sql=s; self.ts=tokens or tokenize(s); self.i=0
    @property
    def tok(self): return self.ts[min(self.i,len(self.ts)-1)]
    def peek(self,n=0): return self.ts[min(self.i+n,len(self.ts)-1)].upper
    def take(self): t=self.tok; self.i+=1; return t
    def eat(self,s):
        if self.peek()==s.upper(): self.i+=1; return True
        return False
    def expect(self,s):
        if not self.eat(s): self.error()
    def error(self,t=None):
        t=t or self.tok
        if t.kind=='eof': raise SQLError('Parser','syntax error at end of input',None,False)
        raise SQLError('Parser','syntax error at or near "'+t.raw+'"',t.pos)
    def ident(self):
