        return self.take().value
    def qualified(self):
        a=[self.ident()]
        while self.eat('.'): a.append(self.ident())
        return a
    def typ(self):
        b=self.ident().upper(); b=ALIASES.get(b,b); args=()
        if b=='DOUBLE' and self.eat('PRECISION'): pass
        if b=='CHARACTER' and self.eat('VARYING'): b='VARCHAR'
        if b in ('TIMESTAMP','TIME') and self.eat('WITH'):
            self.expect('TIME'); self.expect('ZONE'); b+=' WITH TIME ZONE'
        if b in ('TIMESTAMP','TIME') and self.eat('WITHOUT'): self.expect('TIME'); self.expect('ZONE')
        if self.eat('('):
            if b in ('STRUCT','UNION'):
                pairs=[]
                while True:
                    n=self.ident(); pairs.append((n,self.typ()))
                    if not self.eat(','): break
