            self.expect(')')
        elif b=='DECIMAL': args=(18,3)
        t=Type(b,args)
        while self.eat('['):
            if self.eat(']'): t=Type('LIST',(t,))
            else: size=int(self.take().value); self.expect(']'); t=Type('ARRAY',(t,size))
        return t
    def expr_list(self,closing=None):
        a=[]
        if closing and self.eat(closing): return a
        while True:
            a.append(self.expr())
            if not self.eat(','): break
        if closing: self.expect(closing)
        return a
    def expr(self,minprec=0):
