        else: self.error(t)
        while True:
            u=self.peek()
            if u=='::':
                self.take(); x=Node('cast',self.typ(),[x],x.pos); continue
            if u=='[':
                self.take(); i=None if self.peek()==':' else self.expr()
                if self.eat(':'):
