            ar.append((e,desc,nul))
            if not self.eat(','): break
        return ar
    def window(self):
        if not self.eat('('): return self.ident()
        w={}
        if self.eat('PARTITION'): self.expect('BY'); w['partition']=self.expr_list()
        if self.eat('ORDER'): self.expect('BY'); w['order']=self.order_list()
        if self.peek() in ('ROWS','RANGE','GROUPS'):
            w['frame_kind']=self.take().upper; toks=[]
            while self.peek() not in (')','EOF'): toks.append(self.take().upper)
            w['frame']=toks
