    def projections(self):
        out=[]
        while True:
            e=self.expr(); alias=None
            if e.k=='star' and self.peek() in ('EXCLUDE','EXCEPT','REPLACE','RENAME'):
                while self.peek() in ('EXCLUDE','EXCEPT','REPLACE','RENAME'):
                    mod=self.take().upper; vals=[]
                    par=self.eat('(')
                    while True:
                        if mod in ('EXCLUDE','EXCEPT'): vals.append(self.ident())
                        else:
