            elif self.tok.kind in ('word','qid') and self.peek() not in STOP_ALIAS and self.peek() not in ('EOF',): alias=self.ident()
            out.append((e,alias))
            if not self.eat(','): break
            if self.peek() in ('FROM','WHERE','GROUP','HAVING','ORDER','LIMIT',';','EOF',')'): break
        return out
    def source(self):
        p=self.tok.pos
