            else:
                src=self.from_clause(); self.expect(')')
        elif self.tok.kind=='string': src={'kind':'file','path':self.take().value,'pos':p}
        else:
            names=self.qualified(); src={'kind':'table','name':names,'pos':p}
            if self.eat('('): src={'kind':'function','name':'.'.join(names).lower(),'args':self.function_args(), 'pos':p}
        if self.eat('WITH'): self.expect('ORDINALITY'); src['ordinality']=True
        if self.eat('AS'): src['alias']=self.ident()
        elif self.tok.kind in ('word','qid') and self.peek() not in STOP_ALIAS and self.peek() not in ('EOF',): src['alias']=self.ident()
        if self.eat('('):
            ar=[]
            while True:
                ar.append(self.ident())
                if not self.eat(','): break
            self.expect(')'); src['columns']=ar
        return src
    def function_args(self):
        ar=[]
        if self.eat(')'): return ar
        while True:
            if self.peek(1) in ('=','=>',':='):
                n=self.take().value; self.take(); ar.append(Node('named',n,[self.expr()],self.tok.pos))
            else: ar.append(self.expr())
            if not self.eat(','): break
        self.expect(')'); return ar
    def from_clause(self):
