        elif self.eat('VALUES'):
            rows=[]
            while True:
                self.expect('('); rows.append(self.expr_list(')'))
                if not self.eat(','): break
            q={'kind':'values','rows':rows}
        else:
            firstfrom=self.eat('FROM')
            q={'kind':'select'}
            if firstfrom:
                q['from']=self.from_clause()
