        return q
    def all_statements(self):
        stmts=[]
        while self.peek()!='EOF':
            if self.eat(';'): continue
            st=self.statement(); stmts.append(st)
            if self.peek() not in (';','EOF'): self.error()
            self.eat(';')
        return stmts
    def statement(self):
        start=self.tok.pos; u=self.peek()
        if u in ('SELECT','WITH','VALUES','FROM','('): return {'kind':'query','q':self.query(),'pos':start}
        if u in ('DESCRIBE','DESC','SUMMARIZE'):
            self.take()
            if self.peek() in ('SELECT','WITH','FROM','VALUES'): q=self.query(); name=None
            else: name=self.qualified(); q=None
            return {'kind':'describe' if u!='SUMMARIZE' else 'summarize','query':q,'name':name,'pos':start}
